// Android paints a yellow highlight (and on some OEMs a coloured outline) over any field filled from a
// keyboard/autofill suggestion. Our inputs draw their own Atelier field states, so make that overlay
// transparent in the app theme. Lives in a config plugin because android/ is regenerated by prebuild.
const { withAndroidStyles, AndroidConfig } = require('expo/config-plugins');

module.exports = function withAndroidAutofillHighlight(config) {
  return withAndroidStyles(config, (cfg) => {
    cfg.modResults = AndroidConfig.Styles.assignStylesValue(cfg.modResults, {
      add: true,
      parent: AndroidConfig.Styles.getAppThemeGroup(),
      name: 'android:autofilledHighlight',
      value: '@android:color/transparent',
    });
    return cfg;
  });
};
